/**
 * Programmatic migration runner — applies pending SQL migrations from
 * `packages/db/drizzle/` (generated by `pnpm db:generate`) and records them
 * in Drizzle's migrations table.
 *
 * Usage:
 *   pnpm db:migrate            # from the repo root
 *   pnpm migrate               # from packages/db
 *
 * Run this on deploy (e.g. before starting the server in your container
 * entrypoint). `db:push` remains available for local prototyping only.
 *
 * Set MIGRATIONS_DIR to point at the migrations folder when the default
 * relative path does not survive your packaging (e.g. a Docker image that
 * copies the folder elsewhere).
 */

import path from "node:path";
import { fileURLToPath } from "node:url";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";
import postgres from "postgres";

const postgresUrl = process.env.POSTGRES_URL;

async function main() {
  if (!postgresUrl) {
    console.error("Missing POSTGRES_URL");
    process.exit(1);
  }

  const migrationsFolder =
    process.env.MIGRATIONS_DIR ??
    path.join(path.dirname(fileURLToPath(import.meta.url)), "../drizzle");

  // Migrations must run serially on a dedicated connection; close it as soon
  // as they finish so the process can exit cleanly.
  const client = postgres(postgresUrl, { max: 1 });

  try {
    console.log(`Applying migrations from ${migrationsFolder}...`);
    await migrate(drizzle(client), { migrationsFolder });
    console.log("Migrations applied.");
  } finally {
    await client.end();
  }
}

main().catch((error) => {
  console.error("Migration failed:", error);
  process.exit(1);
});
